<section class="page-hero"><div><span class="eyebrow">GOOD THINGS, CONNECTED</span><h1><?= e($title) ?></h1><p><?= t('An editorial directory. External sites have their own terms and privacy practices.') ?></p></div><span class="page-hero-art"><?= icon('compass') ?></span></section><div class="directory-grid"><?php $rows=$a->db->all('SELECT * FROM cy_links WHERE active=1 ORDER BY sort_order,id DESC LIMIT 300');foreach($rows as $link): ?><a class="directory-card panel glass reveal" href="<?= e($link['url']) ?>" target="_blank" rel="noopener noreferrer"><span class="directory-monogram"><?= e(strtoupper(substr((string)parse_url($link['url'],PHP_URL_HOST),0,1))) ?></span><div class="grow"><small class="eyebrow"><?= e($link['group_name']) ?></small><h3><?= e($link['name']) ?></h3><p><?= e($link['description']) ?></p><small class="muted"><?= e(parse_url($link['url'],PHP_URL_HOST)) ?></small></div><?= icon('arrow') ?></a><?php endforeach ?></div><?php if(!$rows){empty_state();} ?>
